    static func eventJSON(_ e: Ev) -> [String: Any] {
        switch e {
        case .text(let s): return ["type": "text", "text": s]
        case .backspace: return ["type": "backspace"]
        case .forwardDelete: return ["type": "forward_delete"]
        case .deleteWord: return ["type": "delete_word"]
        case .deleteLine: return ["type": "delete_line"]
        case .selectAll: return ["type": "select_all"]
        case .undo: return ["type": "undo"]
        case .unsupported: return ["type": "unsupported"]
        case .move(let m, let sel):
            let name: String
            switch m {
            case .left: name = "left"
            case .right: name = "right"
            case .wordLeft: name = "word_left"
            case .wordRight: name = "word_right"
            case .lineStart: name = "line_start"
            case .lineEnd: name = "line_end"
            }
            return ["type": "move", "move": name, "select": sel]
        }
    }

    static func candJSON(_ c: VocabDiff.Candidate?) -> Any {
        guard let c else { return NSNull() }
        return ["heard": c.heard, "wanted": c.wanted]
    }

    static func learnCases() -> [[String: Any]] {
        var out: [[String: Any]] = candidatePairs.map { pasted, edited in
            ["kind": "candidate", "pasted": pasted, "edited": edited,
             "expected": candJSON(VocabDiff.candidate(pasted: pasted, edited: edited))]
        }
        for (pasted, evs) in replayCases {
            var m = ReplayModel(pasted)
            for e in evs { m.apply(e) }
            let res = m.result
            out.append(["kind": "replay", "pasted": pasted, "events": evs.map(eventJSON),
                        "result": res.map { $0 as Any } ?? NSNull(), "frozen": m.frozen.map { $0 as Any } ?? NSNull(),
                        "expected": candJSON(res.flatMap { VocabDiff.candidate(pasted: pasted, edited: $0) })])
        }
        return out
    }

