    // MARK: IO
    static func encode(_ obj: Any) -> Data {
        (try? JSONSerialization.data(withJSONObject: obj, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes])) ?? Data()
    }

    static func all() -> [(String, [[String: Any]])] {
        [("cleanup.json", cleanupCases()), ("learn.json", learnCases()), ("dictionary.json", dictCases())]
    }

    static func dump(dir: String) -> Int32 {
        try? FileManager.default.createDirectory(atPath: dir, withIntermediateDirectories: true)
        for (name, cases) in all() {
            var d = encode(cases); d.append(0x0A)
            do { try d.write(to: URL(fileURLWithPath: dir).appendingPathComponent(name)) }
            catch { FileHandle.standardError.write(Data("cannot write \(name): \(error)\n".utf8)); return 1 }
            print("wrote \(name): \(cases.count) cases")
        }
        return 0
    }

    static func canon(_ x: Any) -> String {
        (try? JSONSerialization.data(withJSONObject: x, options: [.sortedKeys, .fragmentsAllowed, .withoutEscapingSlashes]))
            .flatMap { String(data: $0, encoding: .utf8) } ?? "\(x)"
    }

    /// Re-runs the real code over the committed vectors; non-zero exit on any mismatch.
    static func check(dir: String) -> Int32 {
        var fails = 0, total = 0
        for (name, _) in all() {
            guard let d = try? Data(contentsOf: URL(fileURLWithPath: dir).appendingPathComponent(name)),
                  let cases = try? JSONSerialization.jsonObject(with: d) as? [[String: Any]] else {
                print("FAIL \(name): unreadable"); fails += 1; continue
            }
            for (i, c) in cases.enumerated() {
                total += 1
                var got: Any, want: Any = c["expected"] ?? NSNull()
                switch name {
                case "cleanup.json":
                    got = cleanText(c["input"] as! String, bundleId: c["bundle_id"] as! String)
                case "dictionary.json":
                    let es = (c["entries"] as! [[String: Any]]).map {
                        DictEntry(phrase: $0["phrase"] as! String, replacement: $0["replacement"] as? String, learned: $0["learned"] as? Bool)
                    }
                    got = Post.finalize(c["input"] as! String, before: c["before"] as! String, dictionary: es)
                default:
                    let fresh = learnCases()
                    got = fresh[i]["expected"] ?? NSNull()
                }
                if canon(got) != canon(want) { fails += 1; print("FAIL \(name)[\(i)]: got \(got) want \(want)") }
            }
        }
        print("\(total - fails)/\(total) vector cases match")
        return fails == 0 ? 0 : 1
    }
